// MARK <name>: one instant mark when something the user waits for becomes visible (the content of a screen, the
// end of a spinner), fed by PerfHooks.mark(name) from the main code. plan.json metrics can start or end at it.
object MarkTrace {
    var tracer: SectionTracer = PlatformSectionTracer

    fun mark(name: String) {
        tracer.beginSection("MARK $name")
        tracer.endSection()
    }
}
